# install and build in a Workspace of feature-home; commit even the failed build
node --input-type=module <<'JS'
const { LayerFS } = await import("@layerfs/agent");
const lf = await LayerFS.open(process.env.LAYERFS_PROJECT);
try {
  const { sandbox } = await lf.sandbox.create();
  const ws = await lf.workspace.mount(sandbox, "feature-home");
  console.log(`Sandbox ${sandbox}, Workspace ${ws.path}`);
  const install = await lf.workspace.exec(ws, "sh install.sh");
  console.log(`$ sh install.sh\n${install.stdout}${install.stderr}[exit ${install.exitCode}]`);
  const build = await lf.workspace.exec(ws, "sh build.sh");
  console.log(`$ sh build.sh\n${build.stdout}${build.stderr}[exit ${build.exitCode}]`);
  const c = await lf.workspace.commit(ws, `sh install.sh; sh build.sh (exit ${build.exitCode})`);
  console.log("commit", c.kind);
  await lf.workspace.unmount(ws);
  await lf.sandbox.close(sandbox);
} finally {
  await lf.close();
}
