# start the server in the background; unmount is refused while it runs
node --input-type=module <<'JS'
const { LayerFS, isRefusal } = await import("@layerfs/agent");
const { LayerFSBackend } = await import("@layerfs/backend");
const lf = await LayerFS.open(process.env.LAYERFS_PROJECT);
const be = LayerFSBackend.of(lf);
try {
  const { sandbox } = await lf.sandbox.create();
  const ws = await lf.workspace.mount(sandbox, "feature-home");
  const server = await be.daemon.process.start(ws, "sh serve.sh");
  console.log(server.kind, server.process);
  try {
    await lf.workspace.unmount(ws);
  } catch (error) {
    if (!isRefusal(error, "Busy")) throw error;
    console.log(`unmount refused ${error.code}: ${error.message}`);
  }
  console.log("stop", (await be.daemon.process.cancel(server.process)).kind);
  console.log("commit", (await lf.workspace.commit(ws, "sh serve.sh: dev cache")).kind);
  await lf.workspace.unmount(ws);
  await lf.sandbox.close(sandbox);
} finally {
  await lf.close();
}
