# the fs write moves the head after the mount; the commit merges with it
node --input-type=module <<'JS'
const { LayerFS } = await import("@layerfs/agent");
const lf = await LayerFS.open(process.env.LAYERFS_PROJECT);
try {
  const { sandbox } = await lf.sandbox.create();
  const ws = await lf.workspace.mount(sandbox, "feature-home");
  console.log("fs.write CHANGELOG.md", (await lf.fs.write("feature-home", "/CHANGELOG.md", "- about page", "write /CHANGELOG.md")).kind);
  const r = await lf.workspace.exec(ws, "echo \"PORT=3000\" > .env.example");
  console.log(`$ echo "PORT=3000" > .env.example\n[exit ${r.exitCode}]`);
  const c = await lf.workspace.commit(ws, "add .env.example");
  console.log("commit", c.kind, c.merged ? "· was stale, merged with the head first" : "");
  await lf.workspace.unmount(ws);
  await lf.sandbox.close(sandbox);
} finally {
  await lf.close();
}
